const items=document.querySelectorAll('.reveal');if('IntersectionObserver'in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});items.forEach(x=>observer.observe(x))}else items.forEach(x=>x.classList.add('visible'));
const form=document.getElementById('gpm-contact-form'),status=document.getElementById('form-status');form?.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);const msg=['PEDIDO DE CONTACTO | GPM CONECTA','Nome: '+d.get('name'),'Empresa: '+(d.get('company')||'Não indicada'),'Email: '+d.get('email'),'Telefone: '+(d.get('phone')||'Não indicado'),'Área: '+d.get('area'),'Mensagem: '+d.get('message')].join('\n');try{await navigator.clipboard.writeText(msg);status.textContent='Pedido preparado e copiado. Ainda não foi enviado à GPM Conecta.'}catch{status.textContent='Não foi possível copiar automaticamente. O pedido não foi enviado.'}});
